"""Migrated Meridian CRM 4.2 order validation rules."""

from decimal import Decimal, InvalidOperation
from typing import Any


def _value(row: dict | None, column: str) -> Any:
    if row is None:
        return ""
    return row.get(column, "")


def _number(value: Any) -> Decimal:
    if value is None or value == "":
        return Decimal(0)
    try:
        return Decimal(str(value))
    except (InvalidOperation, ValueError):
        return Decimal(0)


def _lookup(
    tables: dict | None,
    table_name: str,
    key_column: str,
    key_value: Any,
    output_column: str,
) -> Any:
    if tables is None:
        return ""

    for row in tables.get(table_name, []):
        if row.get("DEL_FLG", "") == "Y":
            continue
        if row.get(key_column, "") == key_value:
            return row.get(output_column, "")
    return ""


def validate(
    record: dict,
    old: dict | None = None,
    event: str = "INSERT",
    tables: dict | None = None,
    table: str = "ORD_HEADER",
) -> list[dict]:
    """Validate an order header or order line and return all rule failures."""
    errors: list[dict] = []
    old_record = {} if event == "INSERT" else (old or {})

    if table == "ORD_HEADER":
        # ORD-001
        if event in ("INSERT", "UPDATE"):
            disc_pct = _number(_value(record, "DISC_PCT"))
            if not (disc_pct >= 0 and disc_pct <= 100):
                errors.append(
                    {
                        "code": "E5001",
                        "message": "Discount out of range",
                        "severity": "BLOCK",
                    }
                )

        # ORD-002
        if event == "UPDATE":
            disc_pct = _number(_value(record, "DISC_PCT"))
            owner_role = _lookup(
                tables,
                "USR_MASTER",
                "USR_ID",
                _value(record, "OWNER_UID"),
                "ROLE_ID",
            )
            if disc_pct > 20 and owner_role != "MGR" and owner_role != "ADMIN":
                errors.append(
                    {
                        "code": "E5002",
                        "message": "Discount over 20 percent requires manager role",
                        "severity": "BLOCK",
                    }
                )

        # ORD-003
        if event == "UPDATE":
            if (
                _value(old_record, "STAT_CD") == "I"
                and _value(record, "STAT_CD") != "I"
                and _value(record, "STAT_CD") != "X"
            ):
                errors.append(
                    {
                        "code": "E5003",
                        "message": "Invoiced order can only be cancelled",
                        "severity": "BLOCK",
                    }
                )

    elif table == "ORD_LINE":
        # ORD-004
        if event in ("INSERT", "UPDATE"):
            if not (_number(_value(record, "QTY")) > 0):
                errors.append(
                    {
                        "code": "E5004",
                        "message": "Quantity must be positive",
                        "severity": "BLOCK",
                    }
                )

        # ORD-005
        if event == "INSERT":
            active_flag = _lookup(
                tables,
                "PROD_MASTER",
                "PROD_ID",
                _value(record, "PROD_ID"),
                "ACTIVE_FLG",
            )
            if active_flag != "Y":
                errors.append(
                    {
                        "code": "E5005",
                        "message": "Product not active",
                        "severity": "BLOCK",
                    }
                )

    return errors


def is_blocked(errors: list[dict]) -> bool:
    """Return whether any validation failure blocks the write."""
    return any(error.get("severity") == "BLOCK" for error in errors)
